// Normaliza la aplicacion del VSL, arma la nota para GHL y el aviso de Discord.
// El hash SHA-256 para Meta se hace despues, en nodos Crypto nativos (este
// Code node no puede usar require('crypto'): el sandbox de n8n lo bloquea).
const b = $input.first().json.body || {};

const REVENUE_LABEL = {
  '5-10k': '$5,000 - $10,000 / mes',
  '10-20k': '$10,000 - $20,000 / mes',
  '20-40k': '$20,000 - $40,000 / mes',
  '50k+': '$50,000+ / mes'
};

// Rangos de facturacion que Meta recibe como QualifiedLead.
const REVENUE_10K_PLUS = ['10-20k', '20-40k', '50k+'];

const dash = (v) => (v === undefined || v === null || String(v).trim() === '') ? '-' : String(v).trim();
const yesNo = (v) => v === 'si' ? 'Si' : (v === 'no' ? 'No' : '-');

const parts = String(b.full_name || '').trim().split(/\s+/);
const firstName = parts.shift() || '';
const lastName = parts.join(' ');

// Regla unica: ser dueno de una compania de pintura en EE.UU. La facturacion
// no descalifica: el lead llega igual a Discord, GHL y el Sales Dashboard. Se
// calcula con la respuesta cruda y no con el flag 'qualified' que manda el
// sitio, para que n8n decida igual aunque el sitio este desactualizado.
const isOwner = b.owner_us_painting_company === 'si';
const qualified = isOwner;
// Para Meta: todo dueno manda Lead, pero QualifiedLead (el evento con el que
// optimiza la campana) solo sale si factura $10k+ al mes. Los de $5k-$10k se
// califican a mano desde el boton Meta Qualify del Sales Dashboard.
const metaQualified = isOwner && REVENUE_10K_PLUS.includes(b.monthly_revenue);

const revenue = REVENUE_LABEL[b.monthly_revenue] || dash(b.monthly_revenue);
const email = String(b.email || '').trim().toLowerCase();
const phone = String(b.phone || '').trim();

// Meta quiere el telefono como digitos con codigo de pais, sin '+' ni ceros
// a la izquierda. Asume EE.UU. si vienen 10 digitos.
let phoneDigits = phone.replace(/\D/g, '');
if (phoneDigits.length === 10) phoneDigits = '1' + phoneDigits;

const note = [
  isOwner ? 'APLICACION VSL - LEAD NUEVO' : 'APLICACION VSL - NO ES DUENO EN EE.UU.',
  '',
  `1. Dueno de compania de pintura en EE.UU.: ${yesNo(b.owner_us_painting_company)}`,
  `2. Facturacion mensual: ${revenue}`,
  `3. Licencia y seguro en regla: ${yesNo(b.licensed_insured)}`,
  `4. Area de servicio: ${dash(b.service_area)}`,
  '',
  `Compania: ${dash(b.company)}`,
  `Consentimiento SMS: ${b.sms_consent ? 'Si' : 'No'}`,
  `Enviado: ${b.submitted_at || new Date().toISOString()}`,
  `Pagina: ${dash(b.page)}`
].join('\n');

// Aviso a Discord con TODOS los datos del formulario. Para los que no son
// duenos es el unico registro: ellos no entran a GHL.
const fields = [
  { name: 'Nombre', value: dash(b.full_name), inline: true },
  { name: 'Compania', value: dash(b.company), inline: true },
  { name: 'Email', value: dash(email), inline: false },
  { name: 'Telefono', value: dash(phone), inline: true },
  { name: 'Consentimiento SMS', value: b.sms_consent ? 'Si' : 'No', inline: true },
  { name: 'Area de servicio', value: dash(b.service_area), inline: false },
  { name: '1. Dueno en EE.UU.', value: yesNo(b.owner_us_painting_company), inline: true },
  { name: '2. Facturacion mensual', value: revenue, inline: true },
  { name: '3. Licencia y seguro', value: yesNo(b.licensed_insured), inline: true }
];

const discord = {
  username: 'Topcoat VSL',
  embeds: [{
    title: isOwner ? '🔶 NEW VSL LEAD' : 'Llego una aplicacion VSL - NO ES DUENO EN EE.UU.',
    color: isOwner ? 3066993 : 15158332,
    fields,
    footer: { text: dash(b.page) },
    timestamp: b.submitted_at || new Date().toISOString()
  }]
};

return [{
  json: {
    firstName,
    lastName,
    email,
    phone,
    phoneDigits,
    companyName: b.company || '',
    qualified,
    metaQualified,
    // meta-qualified le avisa al Sales Dashboard que Meta ya recibio
    // QualifiedLead, para que el boton Meta Qualify no lo mande dos veces.
    tags: metaQualified ? ['top-coat-media', 'vsl', 'meta-qualified'] : ['top-coat-media', 'vsl'],
    note,
    discord,
    fbc: b.fbc || '',
    fbp: b.fbp || '',
    user_agent: b.user_agent || '',
    fb_event_id: b.fb_event_id || '',
    page: b.page || '',
    submitted_at: b.submitted_at || new Date().toISOString()
  }
}];

const j = $input.first().json;

// Cero senal a Facebook para los que no son duenos de compania de pintura
// en EE.UU. Devolver [] hace que el nodo 'Meta CAPI - Lead' simplemente no
// corra para este item.
if (!j.qualified) {
  return [];
}

const eventTime = j.submitted_at ? Math.floor(new Date(j.submitted_at).getTime() / 1000) : Math.floor(Date.now() / 1000);

const userData = {
  em: j.emHash ? [j.emHash] : undefined,
  ph: j.phHash ? [j.phHash] : undefined,
  fbc: j.fbc || undefined,
  fbp: j.fbp || undefined,
  client_user_agent: j.user_agent || undefined
};

// Todo dueno manda Lead (mismo event_id que el pixel del navegador).
const data = [
  {
    event_name: 'Lead',
    event_time: eventTime,
    event_id: j.fb_event_id || undefined,
    event_source_url: j.page || undefined,
    action_source: 'website',
    user_data: userData,
    custom_data: {
      content_name: 'Aplicacion VSL',
      content_category: 'calificado'
    }
  }
];

// QualifiedLead solo para los que facturan $10k+ (metaQualified, ver Normalizar).
if (j.metaQualified) {
  data.push({
    event_name: 'QualifiedLead',
    event_time: eventTime,
    event_id: (j.fb_event_id || 'tcm') + '-qualified',
    event_source_url: j.page || undefined,
    action_source: 'website',
    user_data: userData,
    custom_data: {
      content_name: 'Aplicacion VSL - Calificado'
    }
  });
}

return [{ json: { ...j, metaCapi: { data } } }];
